230	// tableStyles holds the foreground styles for the human table/field views,
231	// matching the activity/session palette: gray ("8") for headers and
232	// secondary cells, white ("7") for the primary (first-column) value. When
233	// color is disabled (non-TTY, NO_COLOR — e.g. piped output and tests) the
234	// styles are no-ops and output is plain.
235	type tableStyles struct {
236		enabled bool
237		header  lipgloss.Style
238		primary lipgloss.Style
