272	// printTable writes headers plus one row per item, columns aligned on the
273	// plain-text widths so ANSI color codes don't throw off the layout (they're
274	// applied after padding). Callers handle the empty case.
275	func printTable[T any](w io.Writer, headers []string, items []T, row func(T) []string) error {
276		st := newTableStyles(w)
277		rows := make([][]string, len(items))
278		for i, it := range items {
279			rows[i] = row(it)
280		}
281		widths := columnWidths(headers, rows)
282	
283		var b strings.Builder
284		writeTableRow(&b, headers, widths, func(int) lipgloss.Style { return st.header }, st)
285		for _, r := range rows {
286			writeTableRow(&b, r, widths, st.columnStyle, st)
287		}
288		if _, err := io.WriteString(w, b.String()); err != nil {
289			return fmt.Errorf("render table: %w", err)
290		}
291		return nil
292	}
