323	// columnWidths returns the max plain-text width of each column across the
324	// headers and all rows.
325	func columnWidths(headers []string, rows [][]string) []int {
326		widths := make([]int, len(headers))
327		for i, h := range headers {
328			widths[i] = lipgloss.Width(h)
329		}
330		for _, r := range rows {
331			for i, c := range r {
332				if i < len(widths) && lipgloss.Width(c) > widths[i] {
333					widths[i] = lipgloss.Width(c)
334				}
335			}
336		}
337		return widths
338	}
